{"query": "
-- Check current state of theme_analyst role and any existing policies
SELECT rolname, rolsuper, rolinherit, rolcreaterole, rolcreatedb, rolcanlogin
FROM pg_roles
WHERE rolname = 'theme_analyst';
"}

{"query": "
-- ============================================================
-- STEP 1: Grant SELECT permissions to theme_analyst role
-- ============================================================

-- Grant USAGE on the public schema
GRANT USAGE ON SCHEMA public TO theme_analyst;

-- Reference tables: full SELECT access
GRANT SELECT ON public.lego_themes         TO theme_analyst;
GRANT SELECT ON public.lego_colors         TO theme_analyst;
GRANT SELECT ON public.lego_parts          TO theme_analyst;
GRANT SELECT ON public.lego_part_categories TO theme_analyst;

-- Main data tables: SELECT only (RLS will further restrict rows)
GRANT SELECT ON public.lego_sets            TO theme_analyst;
GRANT SELECT ON public.lego_inventories     TO theme_analyst;
GRANT SELECT ON public.lego_inventory_parts TO theme_analyst;

-- Verify the grants
SELECT grantee, table_name, privilege_type
FROM information_schema.role_table_grants
WHERE grantee = 'theme_analyst'
  AND table_schema = 'public'
ORDER BY table_name, privilege_type;
"}

{"query": "
-- Enable RLS on all three tables
ALTER TABLE public.lego_sets            ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lego_inventories     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lego_inventory_parts ENABLE ROW LEVEL SECURITY;

-- Verify via pg_class
SELECT 
  n.nspname AS schema_name,
  c.relname AS table_name,
  c.relrowsecurity AS rls_enabled
FROM pg_class c
JOIN pg_namespace n ON c.relnamespace = n.oid
WHERE c.relname IN ('lego_sets', 'lego_inventories', 'lego_inventory_parts')
  AND n.nspname = 'public'
ORDER BY c.relname;
"}

{"query": "
-- Test theme_analyst role context — all tests in a single transaction
BEGIN;
SET LOCAL ROLE theme_analyst;

-- TEST A: Total sets visible to theme_analyst (Expected: 2 — Star Wars only)
SELECT 
  'TEST A: Total lego_sets visible' AS test_name,
  COUNT(*) AS count,
  '2 expected (Star Wars only)' AS expectation
FROM lego_sets;

ROLLBACK;
"}
